<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { detalleDocumento,listarDocumentos,obtenerCorrelativo,registrarDocumento,type DocumentoNormativo,type Options } from '../services/documentosNormativos'
const rows=ref<DocumentoNormativo[]>([]),options=ref<Options>({tipos:[],estados:[],oficinas:[],tipos_relacion:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<DocumentoNormativo|null>(null),file=ref<File|null>(null)
const filters=reactive({criterio:'',tipo_documento_id:'',estado_id:'',organo_emisor_id:'',page:1}),form=reactive({tipo_documento_id:'',oficina_id:'',numero_documento:'',titulo:'',fecha_aprobacion:new Date().toISOString().slice(0,10),fecha_vigencia:'',contenido:'',version_de:''})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarDocumentos(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(version?:DocumentoNormativo){Object.assign(form,{tipo_documento_id:version?.tipo_documento_id||'',oficina_id:version?.oficina_id||'',numero_documento:'',titulo:version?.titulo||'',fecha_aprobacion:new Date().toISOString().slice(0,10),fecha_vigencia:'',contenido:version?.contenido||'',version_de:version?.id||''});file.value=null;modal.value=true;if(version)refreshNumber()}
async function refreshNumber(){if(!form.tipo_documento_id||!form.oficina_id)return;try{form.numero_documento=(await obtenerCorrelativo(form.tipo_documento_id,form.oficina_id)).numero}catch{} }
async function save(){if(!form.tipo_documento_id||!form.oficina_id||!form.numero_documento||!form.titulo||!form.fecha_aprobacion||!file.value){error.value='Complete los datos obligatorios y adjunte el documento PDF.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(v!=='')data.append(k,String(v))});data.append('archivo_principal',file.value);saving.value=true;error.value='';try{await registrarDocumento(data);modal.value=false;success.value=form.version_de?'Nueva versión registrada correctamente.':'Documento normativo registrado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:DocumentoNormativo){try{detail.value=await detalleDocumento(item.id)}catch(e){error.value=message(e)}}function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}function size(v?:number){return v?`${(v/1024/1024).toFixed(2)} MB`:'—'}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / MAT / Documentos Normativos</nav><header class="hero"><div class="mark">DN</div><div><small>MAT · LEGAL</small><h1>Documentos normativos</h1><p>Repositorio institucional, control de vigencia y relaciones normativas.</p></div><strong>{{total}} documentos</strong><button @click="open()">+ Nuevo documento</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número o título" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.tipo_documento_id"><option value="">Todos</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado_id"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Oficina emisora<select v-model="filters.organo_emisor_id"><option value="">Todas</option><option v-for="x in options.oficinas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando documentos…</div><div v-else-if="!rows.length" class="empty">No se encontraron documentos normativos.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><div class="icon">PDF</div><div><small>{{item.tipo}}</small><b>{{item.numero_documento}}</b></div><em>{{item.estado}}</em></header><h2>{{item.titulo}}</h2><p>{{item.contenido||'Sin resumen registrado.'}}</p><dl><div><dt>Aprobación</dt><dd>{{item.fecha_aprobacion}}</dd></div><div><dt>Vigencia</dt><dd>{{item.fecha_vigencia||'Desde publicación'}}</dd></div></dl><footer><span>{{item.oficina}}</span><div><button @click="open(item)">Nueva versión</button><button @click="show(item)">Ver ficha</button></div></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{form.version_de?'CONTROL DE VERSIONES':'NUEVO REGISTRO'}}</small><h2>{{form.version_de?'Registrar nueva versión':'Registrar documento normativo'}}</h2></div><button type="button" @click="modal=false">×</button></header><p v-if="form.version_de" class="version">La versión anterior quedará en estado MODIFICADO y se generará la relación correspondiente.</p><div class="grid"><label>Tipo de documento *<select v-model="form.tipo_documento_id" @change="refreshNumber"><option value="">Seleccione</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Oficina emisora *<select v-model="form.oficina_id" @change="refreshNumber"><option value="">Seleccione</option><option v-for="x in options.oficinas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Número *<input v-model.trim="form.numero_documento" maxlength="50"></label><label>Fecha de aprobación *<input v-model="form.fecha_aprobacion" type="date"></label><label>Fecha de vigencia<input v-model="form.fecha_vigencia" type="date"></label></div><label>Título *<textarea v-model.trim="form.titulo" maxlength="500" rows="2"></textarea></label><label>Contenido o resumen<textarea v-model.trim="form.contenido" rows="5"></textarea></label><label>Documento digital PDF *<input type="file" accept="application/pdf" @change="choose"><small>Máximo 20 MB.</small></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar documento'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA NORMATIVA</small><h2>{{detail.tipo}} N.° {{detail.numero_documento}}</h2><p>{{detail.estado}} · {{detail.oficina}}</p></div><button @click="detail=null">×</button></header><h3>{{detail.titulo}}</h3><p class="content">{{detail.contenido||'Sin contenido descriptivo.'}}</p><div class="summary"><div><b>{{detail.fecha_aprobacion}}</b><span>Aprobación</span></div><div><b>{{detail.fecha_vigencia||'—'}}</b><span>Vigencia</span></div><div><b>{{detail.adjuntos?.length||0}}</b><span>Archivos</span></div><div><b>{{(detail.relaciones_origen?.length||0)+(detail.relaciones_destino?.length||0)}}</b><span>Relaciones</span></div></div><h3>Archivos</h3><div class="list"><p v-if="!detail.adjuntos?.length">Sin archivos.</p><div v-for="x in detail.adjuntos" :key="x.id"><b>{{x.nombre_original}}</b><span>{{x.tipo}} · {{size(x.tamano_bytes)}}</span></div></div><h3>Documentos relacionados</h3><div class="list"><p v-if="!detail.relaciones_origen?.length&&!detail.relaciones_destino?.length">Sin relaciones normativas.</p><div v-for="x in detail.relaciones_origen" :key="'o'+x.id"><b>{{x.tipo}}: {{x.documento.tipo}} {{x.documento.numero_documento}}</b><span>{{x.documento.titulo}}</span></div><div v-for="x in detail.relaciones_destino" :key="'d'+x.id"><b>{{x.tipo}}: {{x.documento.tipo}} {{x.documento.numero_documento}}</b><span>{{x.documento.titulo}}</span></div></div><footer><button class="clear" @click="detail=null">Cerrar</button><button @click="detail&&open(detail)">Crear nueva versión</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#596a7b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;border-radius:9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-radius:9px;background:#fff}.cards article>header{display:flex;align-items:center;gap:8px}.icon{padding:7px;border-radius:5px;color:#fff;background:#b44747;font-size:.46rem;font-weight:700}.cards header b,.cards header small{display:block}.cards header em{margin-left:auto;padding:4px 7px;border-radius:10px;background:#edf1f3;font-size:.47rem;font-style:normal}.cards h2{min-height:35px;font-size:.65rem}.cards article>p{min-height:44px;color:#66757c;font-size:.53rem}.cards dl{display:flex;gap:14px}.cards dt{color:#8a969c;font-size:.46rem}.cards dd{margin:2px 0;font-size:.52rem;font-weight:700}.cards footer{margin-top:auto;display:flex;justify-content:space-between;align-items:end;gap:6px}.cards footer span{font-size:.48rem}.cards footer button{border:0;color:var(--accent);background:none;font-size:.48rem;font-weight:700}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.version,.content{padding:11px;border-left:3px solid var(--accent);background:#f3f6f7;font-size:.58rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.modal h3{font-size:.65rem}.list div{padding:8px;border-bottom:1px solid #e8ecee;font-size:.56rem}.list b,.list span{display:block}.list span,.list>p{color:#7d898f}.detail{width:min(100%,900px)}@media(max-width:1000px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}}
</style>
